from typing import TYPE_CHECKING

from markdownify import MarkdownConverter

if TYPE_CHECKING:
    from bs4 import Tag


class _TableComplexityException(Exception):
    pass


class _GFMTableConverter(MarkdownConverter):
    """
    Custom converter that detects complex table features.

    The base markdownify library will silently convert complex HTML tables to
    GFM pipe tables, but this loses information (e.g., merged cells become
    empty cells). This custom converter detects such cases and raises an
    exception to allow fallback to HTML.

    Background:
    - GFM markdown tables don't support colspan/rowspan
    - markdownify doesn't provide rowspan support (issue #121):
      https://github.com/matthewwithanm/python-markdownify/issues/121
    - Instead of silent data loss, we detect complexity and preserve HTML

    Raises TableComplexityException when encountering:
    - colspan > 1
    - rowspan > 1
    - Multiple tbody sections
    """

    def __init__(self, **options):
        super().__init__(**options)
        self._tbody_count = 0

    def convert_td(self, el: "Tag", text: str, parent_tags: set[str]) -> str:
        self._check_cell_complexity(el)
        return super().convert_td(el, text, parent_tags)  # type: ignore[attr-defined]

    def convert_th(self, el: "Tag", text: str, parent_tags: set[str]) -> str:
        self._check_cell_complexity(el)
        return super().convert_th(el, text, parent_tags)  # type: ignore[attr-defined]

    def convert_table(self, el: "Tag", text: str, parent_tags: set[str]) -> str:
        self._tbody_count = len(el.find_all("tbody", recursive=False))
        if self._tbody_count > 1:
            raise _TableComplexityException(
                f"Table has {self._tbody_count} tbody sections (GFM only supports 1)"
            )
        return super().convert_table(el, text, parent_tags)  # type: ignore[attr-defined]

    def _check_cell_complexity(self, el: "Tag") -> None:
        colspan = el.get("colspan", "1")
        rowspan = el.get("rowspan", "1")

        try:
            colspan_str = str(colspan) if colspan else "1"
            rowspan_str = str(rowspan) if rowspan else "1"

            if int(colspan_str) > 1:
                raise _TableComplexityException(
                    f"Table has colspan={colspan_str} (GFM doesn't support colspan)"
                )
            if int(rowspan_str) > 1:
                raise _TableComplexityException(
                    f"Table has rowspan={rowspan_str} (GFM doesn't support rowspan)"
                )
        except ValueError as error:
            raise _TableComplexityException(
                "Table has invalid colspan/rowspan values"
            ) from error


def render_table_content(html_string: str) -> str:
    try:
        converter = _GFMTableConverter(heading_style="ATX")
        gfm_table = converter.convert(html_string).strip()
        return gfm_table
    except _TableComplexityException:
        return html_string

from pathlib import Path
from shutil import copy2
from typing import Callable, Generator, Iterable

from ...expression import ExpressionKind, to_markdown_string
from ...pdf import TITLE_TAGS
from ...extractor.chapter import (
    AssetLayout,
    BlockMember,
    InlineExpression,
    ParagraphLayout,
    Reference,
    RefIdMap,
)
from ..paragraph import render_markdown_paragraph
from .table import render_table_content

_MAX_TOC_LEVELS = 3
_MAX_TITLE_LEVELS = 6


def render_layouts(
    layouts: Iterable[ParagraphLayout | AssetLayout],
    assets_path: Path,
    output_assets_path: Path,
    asset_ref_path: Path,
    toc_level: int,
    ref_id_to_number: RefIdMap | None = None,
) -> Generator[str, None, None]:
    is_first_layout = True
    toc_level = min(toc_level, _MAX_TOC_LEVELS - 1)

    for layout in layouts:
        if is_first_layout:
            is_first_layout = False
        else:
            yield "\n\n"
        if isinstance(layout, AssetLayout):
            yield from _render_asset(
                asset=layout,
                assets_path=assets_path,
                output_assets_path=output_assets_path,
                asset_ref_path=asset_ref_path,
                ref_id_to_number=ref_id_to_number,
            )
        elif isinstance(layout, ParagraphLayout):
            yield from render_paragraph(
                paragraph=layout,
                toc_level=toc_level,
                ref_id_to_number=ref_id_to_number,
            )


def render_paragraph(
    paragraph: ParagraphLayout, toc_level: int, ref_id_to_number: RefIdMap | None = None
) -> Generator[str, None, None]:
    if paragraph.level >= 0 and paragraph.ref in TITLE_TAGS:
        level = min(toc_level + paragraph.level, _MAX_TITLE_LEVELS)
        for _ in range(level + 1):  # level 0 对应 1 个 #
            yield "#"
        yield " "

    def render_member(part: BlockMember | str) -> Generator[str, None, None]:
        if isinstance(part, str):
            yield to_markdown_string(
                kind=ExpressionKind.TEXT,
                content=part,
            )
        elif isinstance(part, InlineExpression):
            latex_content = part.content.strip()
            if latex_content:
                yield to_markdown_string(
                    kind=part.kind,
                    content=latex_content,
                )
        elif ref_id_to_number and isinstance(part, Reference):
            ref_number = ref_id_to_number.get(part.id, 1)
            yield "[^"
            yield str(ref_number)
            yield "]"

    for block in paragraph.blocks:
        yield from render_markdown_paragraph(
            children=block.content,
            render_payload=render_member,
        )


_MemberRender = Callable[[BlockMember | str], Iterable[str]]


def _render_asset(
    asset: AssetLayout,
    assets_path: Path,
    output_assets_path: Path,
    asset_ref_path: Path,
    ref_id_to_number: RefIdMap | None = None,
) -> Generator[str, None, None]:
    def render_member(part: BlockMember | str) -> Generator[str, None, None]:
        if isinstance(part, str):
            yield to_markdown_string(
                kind=ExpressionKind.TEXT,
                content=part,
            )
        elif isinstance(part, InlineExpression):
            latex_content = part.content.strip()
            if latex_content:
                yield to_markdown_string(
                    kind=part.kind,
                    content=latex_content,
                )
        elif ref_id_to_number and isinstance(part, Reference):
            ref_number = ref_id_to_number.get(part.id, 1)
            yield "[^"
            yield str(ref_number)
            yield "]"

    has_content = False

    if asset.title:
        title_str = "".join(
            render_markdown_paragraph(
                children=asset.title,
                render_payload=render_member,
            )
        ).strip()
        if title_str:
            yield title_str
            has_content = True

    yield from _render_asset_content(
        asset=asset,
        assets_path=assets_path,
        output_assets_path=output_assets_path,
        asset_ref_path=asset_ref_path,
        render_member=render_member,
        has_content_before=has_content,
    )
    if asset.ref in ("equation", "table"):
        if asset.content:
            has_content = True
    elif asset.ref == "image":
        if asset.hash:
            has_content = True

    if asset.caption:
        caption_str = "".join(
            render_markdown_paragraph(
                children=asset.caption,
                render_payload=render_member,
            )
        ).strip()
        if caption_str:
            if has_content:
                yield "\n\n"
            yield caption_str


def _render_asset_content(
    asset: AssetLayout,
    assets_path: Path,
    output_assets_path: Path,
    asset_ref_path: Path,
    render_member: _MemberRender,
    has_content_before: bool,
) -> Generator[str, None, None]:
    if asset.ref == "equation":
        content_str = "".join(
            render_markdown_paragraph(
                children=asset.content,
                render_payload=render_member,
            )
        )
        latex_content = content_str.strip()
        if latex_content:
            if has_content_before:
                yield "\n\n"
            yield to_markdown_string(
                kind=ExpressionKind.DISPLAY_BRACKET,
                content=latex_content,
            )

    elif asset.ref == "table":
        if asset.content:
            if has_content_before:
                yield "\n\n"
            yield render_table_content(
                html_string="".join(
                    render_markdown_paragraph(
                        children=asset.content,
                        render_payload=render_member,
                    )
                )
            )

    elif asset.ref == "image":
        yield from _render_image(
            asset=asset,
            assets_path=assets_path,
            output_assets_path=output_assets_path,
            asset_ref_path=asset_ref_path,
            has_content_before=has_content_before,
        )


def _render_image(
    asset: AssetLayout,
    assets_path: Path,
    output_assets_path: Path,
    asset_ref_path: Path,
    has_content_before: bool,
) -> Generator[str, None, None]:
    # 渲染图片
    if asset.hash is None:
        return

    source_file = assets_path / f"{asset.hash}.png"
    if not source_file.exists():
        return

    target_file = output_assets_path / f"{asset.hash}.png"
    if not target_file.exists():
        copy2(source_file, target_file)

    if asset_ref_path.is_absolute():
        image_path = target_file
    else:
        image_path = asset_ref_path / f"{asset.hash}.png"

    # 使用 POSIX 风格路径(markdown 标准)
    image_path_str = str(image_path).replace("\\", "/")

    # 图片的 alt 保持空
    if has_content_before:
        yield "\n\n"
    yield f"![]({image_path_str})"

from typing import Callable, Generator, Iterable

from ...language import is_chinese_char
from .types import HTMLTag, P


def render_markdown_paragraph(
    children: list[str | P | HTMLTag[P]],
    render_payload: Callable[[P | str], Iterable[str]],
) -> Generator[str, None, None]:
    yield from _normalize_paragraph(
        parts=_render_markdown_children(
            children=children,
            render_payload=render_payload,
        ),
    )


def _render_markdown_children(
    children: list[str | P | HTMLTag[P]],
    render_payload: Callable[[P | str], Iterable[str]],
) -> Generator[str, None, None]:
    for child in children:
        if isinstance(child, HTMLTag):
            yield from _render_html_tag(child, render_payload)
        else:
            yield from render_payload(child)


def _render_html_tag(
    tag: HTMLTag[P], render_payload: Callable[[P | str], Iterable[str]]
) -> Generator[str, None, None]:
    tag_name = tag.definition.name

    if not tag.children:
        yield "<"
        yield tag_name
        yield from _render_attributes(tag.attributes)
        yield " />"
    else:
        yield "<"
        yield tag_name
        yield from _render_attributes(tag.attributes)
        yield ">"

        yield from render_markdown_paragraph(tag.children, render_payload)

        yield "</"
        yield tag_name
        yield ">"


def _render_attributes(attributes: list[tuple[str, str]]) -> Generator[str, None, None]:
    for name, value in attributes:
        yield " "
        yield name
        if value:
            yield '="'
            yield from _escape_attribute(value)
            yield '"'


def _escape_attribute(value: str) -> Generator[str, None, None]:
    for char in value:
        if char == "&":
            yield "&amp;"
        elif char == '"':
            yield "&quot;"
        elif char == "<":
            yield "&lt;"
        elif char == ">":
            yield "&gt;"
        else:
            yield char


def _normalize_paragraph(parts: Iterable[str]) -> Generator[str, None, None]:
    last_char: str | None = None
    is_line_head = True
    for part in _split_enters(parts):
        if part != "\n":
            if is_line_head:
                is_line_head = False
                part = part.lstrip()
                if (
                    part
                    and last_char is not None
                    and (not is_chinese_char(last_char) or not is_chinese_char(part[0]))
                ):
                    yield " "
            if part:
                yield part
                part = part.rstrip()
                if part:
                    last_char = part[-1]
        else:
            is_line_head = True


def _split_enters(parts: Iterable[str]) -> Generator[str, None, None]:
    for part in parts:
        if not part:
            continue
        split_parts = part.splitlines()
        yield split_parts[0]
        for i in range(1, len(split_parts)):
            yield "\n"
            yield split_parts[i]

from dataclasses import dataclass
from enum import Enum, auto
from typing import Generator


class ExpressionKind(Enum):
    TEXT = auto()
    INLINE_DOLLAR = auto()  # $ ... $
    DISPLAY_DOUBLE_DOLLAR = auto()  # $$ ... $$
    INLINE_PAREN = auto()  # \( ... \)
    DISPLAY_BRACKET = auto()  # \[ ... \]


@dataclass
class ParsedItem:
    kind: ExpressionKind
    content: str

    def reverse(self) -> str:
        return to_markdown_string(self.kind, self.content)


def encode_expression_kind(kind: ExpressionKind) -> str:
    if kind == ExpressionKind.INLINE_DOLLAR:
        return "$"
    elif kind == ExpressionKind.DISPLAY_DOUBLE_DOLLAR:
        return "$$"
    elif kind == ExpressionKind.INLINE_PAREN:
        return "\\("
    elif kind == ExpressionKind.DISPLAY_BRACKET:
        return "\\["
    else:  # TEXT
        return "text"


def decode_expression_kind(kind_str: str) -> ExpressionKind:
    if kind_str == "$":
        return ExpressionKind.INLINE_DOLLAR
    elif kind_str == "$$":
        return ExpressionKind.DISPLAY_DOUBLE_DOLLAR
    elif kind_str == "\\(":
        return ExpressionKind.INLINE_PAREN
    elif kind_str == "\\[":
        return ExpressionKind.DISPLAY_BRACKET
    elif kind_str == "text":
        return ExpressionKind.TEXT
    else:
        raise ValueError(f"Unknown expression kind: {kind_str}")


def to_markdown_string(kind: ExpressionKind, content: str) -> str:
    # LaTEX 基于状态机，故它本身需要转义 `\$` 和 `\(` 等。content 本身包含转义符是最自然的。
    if kind == ExpressionKind.INLINE_DOLLAR:
        return "$" + content + "$"
    elif kind == ExpressionKind.DISPLAY_DOUBLE_DOLLAR:
        return "$$" + content + "$$"
    elif kind == ExpressionKind.INLINE_PAREN:
        return "\\(" + content + "\\)"
    elif kind == ExpressionKind.DISPLAY_BRACKET:
        return "\\[" + content + "\\]"
    else:
        # 反而是 Markdown 文档本身，需要区分 `$` 和 `(` 不是 LaTEX 语法时，才需要转义
        content = content.replace("\\", "\\\\")
        content = content.replace("$", "\\$")
        return content


def parse_latex_expressions(text: str) -> Generator[ParsedItem, None, None]:
    if not text:
        return

    i = 0
    n = len(text)
    buffer = []

    while i < n:
        # Check for backslash
        if text[i] == "\\" and i + 1 < n:
            backslash_count = 0
            j = i
            while j < n and text[j] == "\\":
                backslash_count += 1
                j += 1

            # Handle escaped dollar sign: \$
            # Note: \( and \[ are LaTeX delimiters, not escape sequences
            if backslash_count % 2 == 1 and j < n and text[j] in "$":
                # Odd number of backslashes before $: escaped dollar sign
                # Output pairs of backslashes and the escaped character
                buffer.append("\\" * (backslash_count // 2))
                buffer.append(text[j])
                i = j + 1
                continue

            # Handle pairs of backslashes: \\ -> \
            if backslash_count >= 2:
                # Output pairs of backslashes
                pairs = backslash_count // 2
                buffer.append("\\" * pairs)
                i += pairs * 2
                # If there's an odd backslash left, continue to process it
                if backslash_count % 2 == 1:
                    # Don't increment i, let the next iteration handle the remaining backslash
                    pass
                continue

            # Try to match \[ ... \] (display formula)
            if i + 1 < n and text[i : i + 2] == "\\[":
                # Check backslashes before \[
                backslash_count = 0
                j = i - 1
                while j >= 0 and text[j] == "\\":
                    backslash_count += 1
                    j -= 1

                # If even number of backslashes (including 0), it's a delimiter
                if backslash_count % 2 == 0:
                    result = _find_latex_end(text, i + 2, "\\]", allow_newline=True)
                    if result is not None:
                        end_pos, latex_content = result
                        if buffer:
                            yield ParsedItem(
                                kind=ExpressionKind.TEXT, content="".join(buffer)
                            )
                            buffer = []
                        yield ParsedItem(
                            kind=ExpressionKind.DISPLAY_BRACKET, content=latex_content
                        )
                        i = end_pos
                        continue

            # Try to match \( ... \) (inline formula)
            if i + 1 < n and text[i : i + 2] == "\\(":
                backslash_count = 0
                j = i - 1
                while j >= 0 and text[j] == "\\":
                    backslash_count += 1
                    j -= 1

                if backslash_count % 2 == 0:
                    result = _find_latex_end(text, i + 2, "\\)", allow_newline=False)
                    if result is not None:
                        end_pos, latex_content = result
                        if buffer:
                            yield ParsedItem(
                                kind=ExpressionKind.TEXT, content="".join(buffer)
                            )
                            buffer = []
                        yield ParsedItem(
                            kind=ExpressionKind.INLINE_PAREN, content=latex_content
                        )
                        i = end_pos
                        continue

        # Check for $$ ... $$ (display formula, higher priority than single $)
        if i + 1 < n and text[i : i + 2] == "$$":
            if not _is_escaped(text, i):
                result = _find_latex_end(text, i + 2, "$$", allow_newline=True)
                if result is not None:
                    end_pos, latex_content = result
                    if buffer:
                        yield ParsedItem(
                            kind=ExpressionKind.TEXT, content="".join(buffer)
                        )
                        buffer = []
                    yield ParsedItem(
                        kind=ExpressionKind.DISPLAY_DOUBLE_DOLLAR, content=latex_content
                    )
                    i = end_pos
                    continue

        # Check for $ ... $ (inline formula)
        if text[i] == "$":
            if not _is_escaped(text, i):
                result = _find_latex_end(text, i + 1, "$", allow_newline=False)
                if result is not None:
                    end_pos, latex_content = result
                    if buffer:
                        yield ParsedItem(
                            kind=ExpressionKind.TEXT, content="".join(buffer)
                        )
                        buffer = []
                    yield ParsedItem(
                        kind=ExpressionKind.INLINE_DOLLAR, content=latex_content
                    )
                    i = end_pos
                    continue

        buffer.append(text[i])
        i += 1

    if buffer:
        yield ParsedItem(kind=ExpressionKind.TEXT, content="".join(buffer))


def _is_escaped(text: str, pos: int) -> bool:
    backslash_count = 0
    i = pos - 1
    while i >= 0 and text[i] == "\\":
        backslash_count += 1
        i -= 1
    return backslash_count % 2 == 1


def _find_latex_end(
    text: str, start: int, end_delimiter: str, allow_newline: bool
) -> tuple[int, str] | None:
    n = len(text)
    i = start
    delimiter_len = len(end_delimiter)

    while i < n:
        if not allow_newline and text[i] == "\n":
            return None
        if i + delimiter_len <= n and text[i : i + delimiter_len] == end_delimiter:
            if not _is_escaped(text, i):
                latex_content = text[start:i]
                return (i + delimiter_len, latex_content)
        i += 1
    return None

from dataclasses import dataclass
from pathlib import Path
import json
from typing import Any


@dataclass
class DocumentPackage:
    """Stable renderer input produced by an Extractor."""

    chapters_path: Path
    assets_path: Path
    toc_path: Path | None = None
    cover_path: Path | None = None
    metadata_path: Path | None = None

    @classmethod
    def from_path(cls, path: Path) -> "DocumentPackage":
        cover_path = path / "cover.png"
        return cls(
            chapters_path=path / "chapters",
            assets_path=path / "assets",
            toc_path=path / "toc.xml",
            cover_path=cover_path if cover_path.exists() else None,
            metadata_path=path / "document.json",
        )

    def validate(self, require_toc: bool = False) -> "DocumentPackage":
        if not self.chapters_path.is_dir():
            raise ValueError(f"missing chapters directory: {self.chapters_path}")
        if not self.assets_path.is_dir():
            raise ValueError(f"missing assets directory: {self.assets_path}")
        if require_toc and not self.has_toc():
            raise ValueError("document package is missing toc.xml")
        if self.metadata_path is not None and self.metadata_path.exists():
            data = json.loads(self.metadata_path.read_text(encoding="utf-8"))
            if data.get("schema") != 1:
                raise ValueError("unsupported document package schema")
            self._parse_page_pixel_sizes(data)
        return self

    def write_metadata(self, *, dpi: int | None = None,
                       page_pixel_sizes: dict[int, tuple[int, int]] | None = None) -> None:
        path = self.metadata_path or self.chapters_path.parent / "document.json"
        self.metadata_path = path
        path.parent.mkdir(parents=True, exist_ok=True)
        payload = {"schema": 1, "bbox_coordinate_space": "ocr_pixels",
                   "page_index_base": 1, "dpi": dpi,
                   "page_pixel_sizes": {str(k): list(v) for k, v in (page_pixel_sizes or {}).items()}}
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")

    def page_pixel_sizes(self) -> dict[int, tuple[int, int]]:
        """Return OCR canvas sizes recorded by the Extractor, without OCR cache."""
        if self.metadata_path is None or not self.metadata_path.exists():
            return {}
        payload = json.loads(self.metadata_path.read_text(encoding="utf-8"))
        return self._parse_page_pixel_sizes(payload)

    @staticmethod
    def _parse_page_pixel_sizes(payload: dict[str, Any]) -> dict[int, tuple[int, int]]:
        raw_sizes = payload.get("page_pixel_sizes", {})
        if not isinstance(raw_sizes, dict):
            raise ValueError("page_pixel_sizes must be a mapping")
        sizes: dict[int, tuple[int, int]] = {}
        for raw_index, raw_size in raw_sizes.items():
            try:
                page_index = int(raw_index)
            except (TypeError, ValueError) as error:
                raise ValueError("page_pixel_sizes keys must be page indexes") from error
            if page_index < 1:
                raise ValueError("page_pixel_sizes page indexes must be positive")
            if (
                not isinstance(raw_size, list | tuple)
                or len(raw_size) != 2
                or not all(
                    isinstance(value, int)
                    and not isinstance(value, bool)
                    and value > 0
                    for value in raw_size
                )
            ):
                raise ValueError(
                    "page_pixel_sizes values must be two positive numeric dimensions"
                )
            sizes[page_index] = (int(raw_size[0]), int(raw_size[1]))
        return sizes

    def has_toc(self) -> bool:
        return self.toc_path is not None and self.toc_path.exists()

    def has_cover(self) -> bool:
        return self.cover_path is not None and self.cover_path.exists()

from pathlib import Path
from typing import Callable, Generator, Iterable

from ...common import XMLReader, read_xml
from .chapter import Chapter, decode


def create_chapters_reader(chapters_path: Path) -> Callable[[], Iterable[Chapter]]:
    chapters: XMLReader[Chapter] = XMLReader(
        prefix="chapter",
        dir_path=chapters_path,
        decode=decode,
    )
    head_path = chapters_path / "chapter_head.xml"

    def generate() -> Generator[Chapter, None, None]:
        if head_path.exists():
            root = read_xml(head_path)
            try:
                yield decode(root)
            except Exception as e:
                raise ValueError(f"Failed to decode from: {head_path}") from e

        yield from chapters.read()

    return generate

